#!/usr/bin/env python3
"""Bundle the unchanged dashboard template for the static offline app."""
import json
import hashlib
import re
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from build_plan_dashboard import TEMPLATE

(ROOT / 'pwa/dashboard-template.mjs').write_text(
    '// Generated by scripts/build_pwa_dashboard.py; edit the source template instead.\n'
    + 'export const dashboardTemplate = ' + json.dumps(TEMPLATE, ensure_ascii=True) + ';\n', encoding='utf-8')

# Updating any shell asset changes sw.js, so installed apps fetch a new cache
# without touching the active-plan record. Include this command in asset edits.
assets = sorted(path for path in (ROOT / 'pwa').iterdir()
                if path.suffix in {'.html', '.mjs', '.css', '.svg', '.webmanifest'} and path.name != 'sw.js')
version = hashlib.sha256(b''.join(path.name.encode() + path.read_bytes() for path in assets)).hexdigest()[:16]
worker = ROOT / 'pwa/sw.js'
source = worker.read_text(encoding='utf-8')
worker.write_text(re.sub(r"const CACHE = 'egginc-mission-shell-[^']+';",
                         "const CACHE = 'egginc-mission-shell-" + version + "';", source), encoding='utf-8')
